  const icon=name=>`<i class="icon" data-lucide="${name}" aria-hidden="true"></i>`;
  const btn=(action,label,ic='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${label}</button>`;
