  const input=(name,label,value,unit='',extra='')=>`<label class="field"><span>${label}</span><div class="unit-input"><input type="number" name="${name}" value="${esc(value)}" step="any" ${extra}>${unit?`<span>${unit}</span>`:''}</div></label>`;
