  const select=(name,label,html)=>`<label class="field"><span>${label}</span><select name="${name}">${html}</select></label>`;
  let state=N.seed(),savedRaw=null,persistError='',conflict=false,page='sku',shopId=state.activeShop,selectedRow='sku-3',strategyId='area',strategyDraft=null,strategyBaseline='',libraryTab='materials',selectedTransfer=new Set(),transfer=null,transferFile='',transferPage=0,transferBusy=false,modal=null,menu=false,plansCollapsed=matchMedia('(max-width:800px)').matches,planQuery='',noticeTimer;
  try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);state=N.migrate(parsed);savedRaw=raw;if(parsed.version!==N.version){localStorage.setItem(KEY+'-before-plan-migration',raw);}} }catch(error){persistError='原型草稿未能读取。当前展示示例，可导出后重试；原存储未覆盖。';conflict=true;}
  shopId=state.activeShop;
